b0cc8b4","name":"Uniform WSFB-100S","url":"https://wilfa.com/cdn/shop/files/coffegrinder_svart-uniform_wsfb-100s_front_6774ba84-e194-4542-b201-6ed787a46350.jpg?crop=center&height=1200&v=1786597419&width=1200","source_url":"https://wilfa.com/products/svart-uniform-steel"},{"id":"23774e2d-01ee-482f-a955-03b36a6d00c2","name":"V60 Ceramic Dripper 02","url":"https://globalhario.com/cdn/shop/files/03_TARU5936.jpg?v=1755236389","source_url":"https://globalhario.com/products/hario-v60-coffee-dripper-ceramic"},{"id":"7cfe4649-911e-47b0-9556-4c384544db10","name":"Varia VS3 Grinder","url":"https://cdn.shopify.com/s/files/1/0013/5951/1651/files/VS3_HERO_S_SCAJ-02.png?v=1721200004","source_url":"https://www.variabrewing.com/products/varia-vs3-grinder"},{"id":"eea15706-68f7-4309-9707-272994bcd472","name":"Victoria Arduino Eagle One","url":"https://victoriaarduino.com/wp-content/uploads/2025/05/VA_EagleOne_acciaio_fronte.png","source_url":"https://victoriaarduino.com/en/products-machines/eagle-one/"},{"id":"04002afc-b652-424d-81e0-2af024933601","name":"Victoria Arduino Mythos MY75","url":"https://victoriaarduino.com/wp-content/uploads/2025/02/1-MY75.jpg","source_url":"https://victoriaarduino.com/en/products-machines/mythos/"},{"id":"9e4bc8b7-b13c-4092-8ee0-af25590b7186","name":"Wacaco Picopresso","url":"https://www.wacaco.com/cdn/shop/products/Picopresso-308-PNG-LD_58cced72-f01b-46de-a2d3-c874f0e41819.png?v=1678885971","source_url":"https://www.wacaco.com/products/picopresso"},{"id":"eb71b554-2203-4605-8a7c-596d6e519fcb","name":"Weber Blind Shaker","url":"https://weberworkshops.com/cdn/shop/products/BlindShaker5.jpg?v=1706399771","source_url":"https://weberworkshops.com/products/blind-shaker"},{"id":"07b64c0a-beac-4b71-95e8-b1f675b64c69","name":"Wilfa Svart Aroma (CGWS-130B)","url":"https://wilfa.com/cdn/shop/files/CoffeGrinder_Classic-Aroma_CGWS-130B_Front_TEK2_Testvinner_PriceRunner_ECBC_ee2641d3-5716-4999-aa62-bf41b1158e37.jpg?crop=center&height=1200&v=1786597387&width=1200","source_url":"https://wilfa.com/products/svart-aroma"},{"id":"915f21d3-2159-4c21-90dc-8aeec519f78b","name":"Zill Coffee Machine","url":"https://cdn.shopify.com/s/files/1/0275/3537/6495/files/Blue-5.jpg?v=1705510777","source_url":"https://www.zillcoffee.com/products/zill-blue-machine"},{"id":"2fd5d5d4-bdcf-4e6d-9a89-d87c4c29b568","name":"xBloom Original","url":"https://xbloom.com/cdn/shop/files/Frame_34597462.png?v=1745744412","source_url":"https://xbloom.com/products/xbloom-original"},{"id":"05a517e1-3f07-47e1-a37c-b941ebe55d5f","name":"xBloom Studio","url":"https://xbloom.com/cdn/shop/files/xbloom_Studio_Midnight_Black_05.webp?v=1777343272","source_url":"https://xbloom.com/products/xbloom-studio"}]'::jsonb) loop
 if not exists(select 1 from public.equipment_models where id=(asset->>'id')::uuid and name=asset->>'name' and not requires_review) then raise exception 'Equipment identity changed: %',asset->>'id'; end if;
 permission := 'owner-confirmed-equipment-images:2026-11-14; asset='||(asset->>'url')||'; source='||(asset->>'source_url');
 images := jsonb_build_array(jsonb_build_object('url',asset->>'url','source_url',asset->>'source_url','alt_ar',(asset->>'name')||' · صورة الموديل','alt_en',(asset->>'name')||' · model photo','usage_status','rights_confirmed','permission_ref',permission));
 update private.content_rights_holds h set replacement_values=jsonb_set(h.replacement_values - 'image_url' - 'image_source_url' - 'image_usage_status' - 'image_permission_ref','{specifications,catalog,images}',images,true),
 evidence_reference='Owner explicitly confirmed permitted original equipment photo use and requested restoration, 2026-11-14. Exact assets: supabase/research/equipment-photos-2026-11-15/photos.json. Other held fields remain unchanged.',
 reviewed_at=now()
 where h.table_name='equipment_models' and h.record_id=(asset->>'id')::uuid and h.active;
 update public.equipment_models e set image_url=asset->>'url',image_source_url=asset->>'source_url',image_usage_status='rights_confirmed',image_permission_ref=permission,
 specifications=jsonb_set(e.specifications,'{catalog,images}',images,true)
 where e.id=(asset->>'id')::uuid and e.name=asset->>'name' and not e.requires_review;
 get diagnostics changed=row_count; total:=total+changed;
end loop;
if total<>144 then raise exception 'Unexpected photo update count: %',total; end if;
end $restore$;
select count(*) as reviewed_models,count(*) filter(where image_url is not null and image_usage_status='rights_confirmed' and nullif(image_permission_ref,'') is not null) as models_with_photos from public.equipment_models where not requires_review;
commit;
